// Generated by forge. The Node version file agrees with package.json (run by .forge/check.sh
// with bun). Usage: bun node_version.mjs <forge-tmp>
// The root .nvmrc / .node-version (a version: "22", "v22.11.0"; a partial version stands for
// the newest release of that line, which nvm, fnm and setup-node install) must satisfy
// package.json engines.node and devEngines.runtime (name "node") version ranges. An alias
// (lts/*, node, lts/iron) is not a version and is reported. The finding is attributed to the
// version file when it changed, else to package.json (line 0).
// Exit 0: nothing found; 1: findings printed ("path:line message"); 3: cannot run.
import { readFileSync } from "node:fs";
import { join } from "node:path";

const [tmp] = process.argv.slice(2);
const changed = new Set((() => { try { return readFileSync(join(tmp, "changed"), "utf8").split("\n").filter(Boolean); } catch { return []; } })());
const read = (p) => { try { return readFileSync(p, "utf8"); } catch { return null; } };
if (typeof Bun === "undefined" || !Bun.semver) {
  console.log("skipped: node_version.mjs needs bun (Bun.semver)");
  process.exit(3);
}
const file = [".nvmrc", ".node-version"].find((f) => read(f) !== null);
const pkgText = read("package.json");
if (!file || pkgText === null) process.exit(0);
let pkg;
try { pkg = JSON.parse(pkgText); } catch { process.exit(0); }

const ranges = [];
if (typeof pkg?.engines?.node === "string") ranges.push(["engines.node", pkg.engines.node]);
const runtimes = pkg?.devEngines?.runtime;
for (const r of Array.isArray(runtimes) ? runtimes : runtimes ? [runtimes] : [])
  if (r?.name === "node" && typeof r.version === "string") ranges.push(["devEngines.runtime", r.version]);
if (!ranges.length) process.exit(0);

const raw = read(file).split(/\r?\n/).map((l) => l.replace(/#.*$/, "").trim()).find(Boolean) ?? "";
const at = changed.has(file) || !changed.has("package.json") ? `${file}:0` : "package.json:0";
const m = /^v?(\d+)(?:\.(\d+))?(?:\.(\d+))?$/.exec(raw);
if (!m) {
  console.log(`${at} ${file} says "${raw}", which is not a version; write the Node version package.json requires (${ranges.map(([k, v]) => `${k} "${v}"`).join(", ")})`);
  process.exit(1);
}
// a partial version is the newest release of its line
const version = `${m[1]}.${m[2] ?? "9999"}.${m[3] ?? "9999"}`;
let bad = false;
for (const [key, range] of ranges) {
  if (!Bun.semver.satisfies(version, range)) {
    console.log(`${at} ${file} (${raw}) does not satisfy package.json ${key} "${range}"; change one so they agree`);
    bad = true;
  }
}
process.exit(bad ? 1 : 0);
